  route('GET', '/api/tokens', ({ user }) => db.apiTokens.filter(t => t.userId === user.id).map(t => ({ id: t.id, name: t.name, createdAt: t.createdAt })));
  route('DELETE', '/api/tokens/:id', ({ user, params }) => {
